import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [input, setInput] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleGenerate = async () => {
    setIsLoading(true);
    setError('');
    try {
      // 调用Coze工作流API
      const response = await axios.post(
        'https://api.coze.com/v1/workflows/7486386392374050870/execute',
        {
          input: input,
        },
        {
          headers: {
            'Authorization': 'Bearer pat_********', // 替换为你的token
          },
        }
      );

      // 检查响应状态码
      if (response.status === 200) {
        console.log('工作流调用成功:', response.data);
        setImageUrl(response.data.imageUrl); // 假设API返回的图片URL字段为imageUrl
      } else {
        setError('工作流调用失败，请重试。');
        console.error('工作流调用失败:', response.statusText);
      }
    } catch (error) {
      setError('生成图片时出错，请检查网络或输入。');
      console.error('生成图片时出错:', error);
    }
    setIsLoading(false);
  };

  // 在返回的JSX中添加错误提示
  {error && <p className="error-message">{error}</p>}

  return (
    <div className="app-container">
      <h1 className="title">AI图片生成器</h1>
      
      <div className="input-area">
        <textarea
          className="prompt-input"
          placeholder="请输入提示词..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
        />
        <button
          className="generate-button"
          onClick={handleGenerate}
          disabled={isLoading}
        >
          {isLoading ? '请稍等30秒...' : '立刻生成'}
        </button>
      </div>

      {isLoading && (
        <div className="loading-image-container">
          <p>生成中...</p>
        </div>
      )}

      {imageUrl && (
        <div className="image-container">
          <img src={imageUrl} alt="生成的图片" className="generated-image" />
        </div>
      )}
    </div>
  );
}

export default App;
